import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { contentSchemaFor, PRACTICE_KINDS, WORD_KINDS, type PracticeKind } from "@/features/practice/model";
import { buildRound } from "@/features/practice/round";

/**
 * The seeded packs (generated by scripts/build-content.mts) must pass the
 * same validation as the editor and produce playable rounds.
 */
const PACKS = [
  "20261110000014_starters_content.sql",
  "20261111000016_gs1_content.sql",
  "20261111000017_starters_skills.sql",
  "20261112000019_video_activities.sql",
];
const ACTIVITY =
  /select v_topic, '([a-z_]+)', '(?:[^']|'')*', '(?:[^']|'')*', \d+, 'published', '((?:[^']|'')*)'::jsonb/g;
const WORD = /select v_level, v_topic, '((?:[^']|'')*)', '(?:[^']|'')*', '[a-z]+', '([0-9a-f-]+)'/g;

function activities(file: string) {
  const sql = readFileSync(join(process.cwd(), "supabase", "migrations", file), "utf8");
  return [...sql.matchAll(ACTIVITY)].map((m) => ({
    kind: m[1] as PracticeKind,
    content: JSON.parse(m[2]!.replace(/''/g, "'")) as unknown,
  }));
}

// Enough topic words for every word game (the real topic words vary per topic).
const words = [
  ...readFileSync(join(process.cwd(), "supabase", "migrations", PACKS[1]!), "utf8").matchAll(WORD),
]
  .slice(0, 6)
  .map((m) => ({ word: m[1]!.replace(/''/g, "'"), meaningVi: "", emoji: m[2]! }));

describe.each(PACKS)("%s", (file) => {
  const list = activities(file);
  it("has activities", () => expect(list.length).toBeGreaterThan(0));
  it("every activity is valid and playable", () => {
    for (const a of list) {
      expect(PRACTICE_KINDS).toContain(a.kind);
      const parsed = contentSchemaFor(a.kind).safeParse(a.content);
      expect(parsed.success, `${a.kind}: ${JSON.stringify(parsed.error?.issues[0])}`).toBe(true);
      if (!WORD_KINDS.includes(a.kind)) {
        expect(buildRound(a.kind, a.content, words).questions.length, a.kind).toBeGreaterThan(0);
      }
    }
  });
});
